tool_calls:
awk '
FNR == NR {
  if ($0 ~ /^#{1,2} /) {
    heading = $0
    sub(/^#{1,2} +/, "", heading)
    anchor = tolower(heading)
    gsub(/ /, "-", anchor)
    toc = toc "- [" heading "](#" anchor ")\n"
  }
  next
}
{
  print
  if (!inserted && $0 ~ /^#{1,2} /) {
    printf "\n%s", toc
    inserted = 1
  }
}' /doc/README.md /doc/README.md > /doc/README.md.tmp && mv /doc/README.md.tmp /doc/README.md
cat /doc/README.md

